-- AI agents: each run (scheduled, manual or asked) and the proposals it leaves for a person to approve.
create table if not exists agent_runs(id uuid primary key default gen_random_uuid(),hospital_id uuid not null references hospitals(id) on delete cascade,agent text not null,trigger text not null default 'manual' check(trigger in ('manual','schedule','ask','event')),status text not null default 'running' check(status in ('running','done','failed')),summary text,findings jsonb not null default '[]',steps jsonb not null default '[]',narrative text,tokens int not null default 0,model text,error text,started_by uuid references users(id) on delete set null,created_at timestamptz not null default now(),finished_at timestamptz);
create index if not exists agent_runs_h on agent_runs(hospital_id,created_at desc);
create table if not exists agent_proposals(id uuid primary key default gen_random_uuid(),hospital_id uuid not null references hospitals(id) on delete cascade,run_id uuid references agent_runs(id) on delete cascade,agent text not null,kind text not null check(kind in ('reorder','roster_shift')),key text not null,title text not null,detail text,payload jsonb not null default '{}',status text not null default 'pending' check(status in ('pending','approved','rejected','expired')),decided_by uuid references users(id) on delete set null,decided_at timestamptz,result jsonb,created_at timestamptz not null default now());
create unique index if not exists agent_proposals_pending on agent_proposals(hospital_id,key) where status='pending';
create index if not exists agent_proposals_h on agent_proposals(hospital_id,status,created_at desc);
create table if not exists agent_settings(hospital_id uuid primary key references hospitals(id) on delete cascade,enabled jsonb not null default '{}',cover jsonb,updated_at timestamptz not null default now());
